def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=collections.Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((color,comp))
    # Repair a one-cell blemish inside an otherwise filled rectangular object.
    for color,comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        area=(r1-r0+1)*(c1-c0+1)
        if area-len(comp)==1:
            for y in range(r0,r1+1):
                for x in range(c0,c1+1):
                    if grid[y][x]!=color: out[y][x]=color
    # Remove singleton noise, except those repaired as holes above.
    for color,comp in comps:
        if len(comp)==1:
            y,x=comp[0]
            if out[y][x]==grid[y][x]: out[y][x]=bg
    return out
